78	  @Override
79	  public Map<ConfigProperty, String> downgrade(HoodieWriteConfig config, HoodieEngineContext context, String instantTime, SupportsUpgradeDowngrade upgradeDowngradeHelper) {
80	    final HoodieTable table = upgradeDowngradeHelper.getTable(config, context);
81	    Map<ConfigProperty, String> tablePropsToAdd = new HashMap<>();
82	    UpgradeDowngradeUtils.runCompaction(table, context, config, upgradeDowngradeHelper);
83	    UpgradeDowngradeUtils.syncCompactionRequestedFileToAuxiliaryFolder(table);
84	
85	    HoodieTableMetaClient metaClient = HoodieTableMetaClient.builder().setConf(context.getStorageConf().newInstance()).setBasePath(config.getBasePath()).build();
86	    List<HoodieInstant> instants = new ArrayList<>();
