88	      // We need to move all the instants - not just completed ones.
89	      instants = metaClient.scanHoodieInstantsFromFileSystem(metaClient.getTimelinePath(),
90	          ActiveTimelineV2.VALID_EXTENSIONS_IN_ACTIVE_TIMELINE, false);
91	    } catch (IOException ioe) {
92	      LOG.error("Failed to get instants from filesystem", ioe);
93	      throw new HoodieIOException("Failed to get instants from filesystem", ioe);
94	    }
95	
96	    if (!instants.isEmpty()) {
97	      InstantFileNameGenerator instantFileNameGenerator = metaClient.getInstantFileNameGenerator();
98	      CommitMetadataSerDeV2 commitMetadataSerDeV2 = new CommitMetadataSerDeV2();
99	      CommitMetadataSerDeV1 commitMetadataSerDeV1 = new CommitMetadataSerDeV1();
100	      ActiveTimelineV1 activeTimelineV1 = new ActiveTimelineV1(metaClient);
101	      context.map(instants, instant -> {
102	        String fileName = instantFileNameGenerator.getFileName(instant);
103	        // Rename the metadata file name from the ${instant_time}_${completion_time}.action[.state] format in version 1.x to the ${instant_time}.action[.state] format in version 0.x.
104	        StoragePath fromPath = new StoragePath(TIMELINE_LAYOUT_V2.getTimelinePathProvider().getTimelinePath(
105	            metaClient.getTableConfig(), metaClient.getBasePath()), fileName);
106	        long modificationTime = instant.isCompleted() ? convertCompletionTimeToEpoch(instant) : -1;
107	        StoragePath toPath = new StoragePath(TIMELINE_LAYOUT_V1.getTimelinePathProvider().getTimelinePath(
108	            metaClient.getTableConfig(), metaClient.getBasePath()), fileName.replaceAll(UNDERSCORE + "\\d+", ""));
109	        boolean success = true;
110	        if (fileName.contains(UNDERSCORE)) {
111	          try {
112	            if (instant.getAction().equals(HoodieTimeline.COMMIT_ACTION) || instant.getAction().equals(HoodieTimeline.DELTA_COMMIT_ACTION)) {
113	              HoodieCommitMetadata commitMetadata =
114	                  commitMetadataSerDeV2.deserialize(instant, metaClient.getActiveTimeline().getInstantDetails(instant).get(), HoodieCommitMetadata.class);
115	              Option<byte[]> data = commitMetadataSerDeV1.serialize(commitMetadata);
116	              String toPathStr = toPath.toUri().toString();
117	              activeTimelineV1.createFileInMetaPath(toPathStr, data, true);
118	              /**
119	               * When we downgrade the table from 1.0 to 0.x, it is important to set the modification
120	               * timestamp of the 0.x completed instant to match the completion time of the
121	               * corresponding 1.x instant. Otherwise,  log files in previous file slices could
122	               * be wrongly attributed to latest file slice for 1.0 readers.
123	               * (see HoodieFileGroup.getBaseInstantTime)
124	               */
125	              if (modificationTime > 0) {
126	                metaClient.getStorage().setModificationTime(toPath, modificationTime);
127	              }
128	              metaClient.getStorage().deleteFile(fromPath);
129	            } else {
130	              success = metaClient.getStorage().rename(fromPath, toPath);
131	            }
