32	@EnumDescription("Bootstrap index type to use for mapping between skeleton and actual data files.")
33	public enum BootstrapIndexType {
34	  @EnumFieldDescription("Maintains mapping in HFile format.")
35	  HFILE(HFileBootstrapIndex.class.getName()),
36	  @EnumFieldDescription("No-op, an empty implementation.")
37	  NONE(NoOpBootstrapIndex.class.getName());
