39	  private final String className;
40	
41	  BootstrapIndexType(String className) {
42	    this.className = className;
43	  }
44	
45	  public String getClassName() {
46	    return className;
47	  }
48	
49	  public static BootstrapIndexType fromClassName(String className) {
50	    for (BootstrapIndexType type : BootstrapIndexType.values()) {
51	      if (type.getClassName().equals(className)) {
52	        return type;
53	      }
54	    }
55	    throw new IllegalArgumentException("No BootstrapIndexType found for class name: " + className);
56	  }
57	
58	  public static String getBootstrapIndexClassName(HoodieConfig config) {
59	    if (!config.getBooleanOrDefault(BOOTSTRAP_INDEX_ENABLE)) {
60	      return BootstrapIndexType.NONE.getClassName();
61	    }
62	    if (config.contains(BOOTSTRAP_INDEX_CLASS_NAME)) {
63	      return config.getString(BOOTSTRAP_INDEX_CLASS_NAME);
64	    } else if (config.contains(BOOTSTRAP_INDEX_TYPE)) {
65	      return BootstrapIndexType.valueOf(config.getString(BOOTSTRAP_INDEX_TYPE)).getClassName();
66	    }
67	    return getDefaultBootstrapIndexClassName(config);
